// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account) public {
        // We only need to call cancel with a role that the caller (address(this)) has
        // or doesn't have. To keep it general, we let fuzz drive role and account.
        // But cancel will revert if the operation is not pending. We need a pending operation
        // to cancel. So schedule one then cancel it.
        // First, ensure we can schedule: we need PROPOSER_ROLE. address(this) has it via setup.
        // We'll schedule a dummy operation with a salt and delay >= minDelay (0).
        bytes32 salt = keccak256(abi.encode(role, account));
        bytes32 id = c.hashOperation(address(1), 0, abi.encode(0), bytes32(0), salt);
        // schedule with delay 0 (minDelay is 0)
        c.schedule(address(1), 0, abi.encode(0), bytes32(0), salt, 0);
        // Now cancel the operation. This should succeed.
        c.cancel(id);
        // After cancel, the operation's timestamp is deleted (0).
        // Now check the property: supportsInterface must return true for IAccessControl
        assertTrue(c.supportsInterface(type(IAccessControl).interfaceId));
    }
}

