pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        // Bound delays to avoid overflow
        delay = bound(delay, 1, 1000000);

        // Schedule an operation from the proposer (this contract)
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // The operation should be pending
        assertTrue(c.isOperationPending(id), "Operation should be pending after scheduling");

        // Now try to cancel with an address that does NOT have PROPOSER_ROLE
        address nonProposer = address(0x1234);
        vm.prank(nonProposer);
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", id));

        // The cancel should revert because nonProposer doesn't have PROPOSER_ROLE
        assertTrue(!success, "Cancel by non-proposer should revert");
    }
}

