pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role) public {
        // For any role, the admin role returned by getRoleAdmin should match the admin role of the DEFAULT_ADMIN_ROLE (0x00) if the role itself is not set,
        // but we can test a general rule: the admin role of the DEFAULT_ADMIN_ROLE (0x00) is initially set to itself (0x00) in the constructor via _setRoleAdmin(TIMELOCK_ADMIN_ROLE, TIMELOCK_ADMIN_ROLE).
        // However, since TIMELOCK_ADMIN_ROLE is keccak256("TIMELOCK_ADMIN_ROLE") and not 0x00, we need a different rule.
        // A simpler general rule: For any role, getRoleAdmin(role) returns the same value as the admin role set for that role.
        // We can test that for a specific role like DEFAULT_ADMIN_ROLE (0x00), the admin role is itself (0x00) because it's never explicitly set to anything else.
        // But the bug returns bytes32(0) for all roles, so for any role where the admin role is not 0, the bug breaks.
        // We'll use the TIMELOCK_ADMIN_ROLE which is set to itself in constructor.
        bytes32 timelockAdminRole = keccak256("TIMELOCK_ADMIN_ROLE");
        bytes32 expectedAdmin = timelockAdminRole; // because _setRoleAdmin(TIMELOCK_ADMIN_ROLE, TIMELOCK_ADMIN_ROLE)
        bytes32 actualAdmin = c.getRoleAdmin(timelockAdminRole);
        assertTrue(actualAdmin == expectedAdmin, "getRoleAdmin should return the admin role that was set");
    }
}

