pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account) public {
        vm.assume(account != address(0) && account != address(this));
        // Grant the role to the account via the public grantRole path
        // First need to get the admin role of the role to grant it
        bytes32 admin = c.getRoleAdmin(role);
        // We need TIMELOCK_ADMIN_ROLE to set admin roles, but we only have that for address(this)
        // Instead, we use the fact that DEFAULT_ADMIN_ROLE is 0x00 which we also have
        // We'll use the TIMELOCK_ADMIN_ROLE directly since address(this) has it
        bytes32 timelockAdmin = 0x74696d656c6f636b5f61646d696e5f726f6c6500000000000000000000000000; // keccak256("TIMELOCK_ADMIN_ROLE")
        // Actually, to keep it simpler, we'll just check that we can grant the role via the public interface
        // The key invariant: after granting a role to an account, that account must have the role
        // But the mutant only changes getRoleAdmin, so we need a rule involving getRoleAdmin
        // The rule: For any role that has been set up with some admin role initially, getRoleAdmin should return that admin role, not zero
        // The initial setup sets TIMELOCK_ADMIN_ROLE admin to itself, PROPOSER_ROLE admin to TIMELOCK_ADMIN_ROLE, EXECUTOR_ROLE admin to TIMELOCK_ADMIN_ROLE
        // And DEFAULT_ADMIN_ROLE has admin of bytes32(0) initially
        // The mutant always returns 0, so for non-zero admin roles it will be wrong
        // Let's check that getRoleAdmin returns a non-zero value for roles that were set up with a non-zero admin
        bytes32 timelockAdminRole = keccak256("TIMELOCK_ADMIN_ROLE");
        bytes32 proposerRole = keccak256("PROPOSER_ROLE");
        bytes32 executorRole = keccak256("EXECUTOR_ROLE");

        // For these three roles, the admin should be timelockAdminRole (which is non-zero)
        bytes32 adminOfTimelock = c.getRoleAdmin(timelockAdminRole);
        bytes32 adminOfProposer = c.getRoleAdmin(proposerRole);
        bytes32 adminOfExecutor = c.getRoleAdmin(executorRole);

        // The property: each of these admins should be equal to timelockAdminRole (non-zero)
        assertTrue(adminOfTimelock == timelockAdminRole && adminOfProposer == timelockAdminRole && adminOfExecutor == timelockAdminRole);
    }
}

