// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role) public {
        // Ensure we can call cancel with a valid operation id that exists
        vm.assume(role != bytes32(0));
        // We need to schedule an operation first so that cancel has something to cancel
        // But cancel requires only PROPOSER_ROLE, which we have (address(this) is proposer)
        // The bug is in getRoleAdmin, so we just test getRoleAdmin directly
        bytes32 expected = keccak256(abi.encode(role));
        bytes32 actual = c.getRoleAdmin(role);
        // In the reference, getRoleAdmin returns the stored adminRole, which is keccak256(abi.encode(role)) only for roles that have been set that way.
        // For any role, getRoleAdmin should return the adminRole stored in _roles[role].adminRole.
        // The mutant always returns keccak256(abi.encode(role)), which will not match for arbitrary roles.
        // We assert that getRoleAdmin returns the correct value: for the role itself, adminRole is keccak256(abi.encode(role)) because that's how it was set up.
        // But for other roles, it's not. We need a general rule: for all roles, getRoleAdmin(role) must equal the adminRole that was set.
        // The only admin roles set are for TIMELOCK_ADMIN_ROLE, PROPOSER_ROLE, EXECUTOR_ROLE - they have adminRole = TIMELOCK_ADMIN_ROLE = keccak256("TIMELOCK_ADMIN_ROLE").
        // So for any role, the adminRole is either 0 (unset) or TIMELOCK_ADMIN_ROLE or something else if set.
        // The fault is that the mutant returns keccak256(abi.encode(role)) which is not the same as any adminRole for most roles.
        // Therefore, assert that getRoleAdmin(role) == getRoleAdmin(role) would be trivial. We need a property that distinguishes.
        // A simple property: getRoleAdmin(role) must return a value that does not depend on role in a deterministic way that matches the reference.
        // Use the fact that the reference stores adminRole separately. For any role, if we call getRoleAdmin twice, we should get the same result.
        // But that works in both. Instead, use the fact that the reference allows setting adminRole via _setRoleAdmin, and the mutant ignores that.
        // So the property: for any role, getRoleAdmin(role) should equal the adminRole that was set for that role (which may be 0 by default).
        // In the reference, unset roles have adminRole = 0 (default). In mutant, they return keccak256(abi.encode(role)) which is not 0.
        // So we assert: getRoleAdmin(role) == bytes32(0x00) for all roles that haven't been explicitly set.
        // But we don't know which roles are set. Simpler: use the fact that the reference's getRoleAdmin for role != bytes32(0) returns either 0 or the set admin.
        // The mutant returns non-zero for all roles. So we assert that getRoleAdmin(role) == bytes32(0x00) for all roles that are not the admin role itself?
        // Actually, the admin role for TIMELOCK_ADMIN_ROLE is TIMELOCK_ADMIN_ROLE itself, which is non-zero.
        // So the property that holds for reference and fails for mutant: getRoleAdmin(role) is a constant function of role? No.
        // Better: for role = bytes32(0x01), the reference returns 0 (since no admin set), mutant returns keccak256(abi.encode(0x01)) != 0.
        // So we can assert: getRoleAdmin(0x01) == 0. That is a specific example, not general.
        // General rule: For any role that is not the admin of itself, getRoleAdmin(role) should return 0 unless explicitly set.
        // But TIMELOCK_ADMIN_ROLE is admin of itself, so that fails.
        // Alternative: assert that getRoleAdmin(role) == getRoleAdmin(role) is always true, but that's true for both.
        // Need a property that distinguishes. The mutant changes return to keccak256(abi.encode(role)), which is a hash of role.
        // The reference returns the stored adminRole, which is set to a specific value.
        // So for any role, if we know the admin role that was set (which we can't read directly), we could check.
        // But we can read the admin role via getRoleAdmin itself. So we can assert that getRoleAdmin(role) should equal the value from a known set.
        // Since we only have access to public functions, we can compare getRoleAdmin(role) to getRoleAdmin(role) from another call? That's idempotent.
        // The only way to get the admin role is via getRoleAdmin. So we cannot distinguish without knowing the expected value.
        // However, we can use the fact that the reference's getRoleAdmin for DEFAULT_ADMIN_ROLE (0x00) returns 0x00 because adminRole is 0x00.
        // The mutant returns keccak256(abi.encode(0x00)) != 0x00.
        // So we can assert: getRoleAdmin(bytes32(0x00)) == bytes32(0x00). That is a general rule about a specific role, but not over fuzz params.
        // The requirement says "a general rule over the fuzz parameters". The fuzz parameter is role.
        // So we need a property that holds for all roles in the reference and fails for at least one role in the mutant.
        // For the reference, for any role, getRoleAdmin(role) is either 0 or the adminRole that was set (which is constant for all set roles: TIMELOCK_ADMIN_ROLE = keccak256("TIMELOCK_ADMIN_ROLE")).
        // For the mutant, getRoleAdmin(role) = keccak256(abi.encode(role)).
        // So a property that holds for reference: getRoleAdmin(role) is either 0 or TIMELOCK_ADMIN_ROLE.
        // But we don't know TIMELOCK_ADMIN_ROLE value. We can compute it: keccak256("TIMELOCK_ADMIN_ROLE").
        // So assert: getRoleAdmin(role) == 0 || getRoleAdmin(role) == keccak256("TIMELOCK_ADMIN_ROLE").
        // This holds for reference because only TIMELOCK_ADMIN_ROLE, PROPOSER_ROLE, EXECUTOR_ROLE have adminRole = TIMELOCK_ADMIN_ROLE, others have 0.
        // The mutant returns keccak256(abi.encode(role)) which is not 0 nor TIMELOCK_ADMIN_ROLE for most roles (e.g., role = 0x01).
        // So this property distinguishes.
        vm.assume(role != bytes32(0)); // avoid DEFAULT_ADMIN_ROLE which has adminRole 0, but the mutant returns non-zero, so still fails. But we can include it.
        bytes32 ret = c.getRoleAdmin(role);
        bytes32 TIMELOCK_ADMIN_ROLE = keccak256("TIMELOCK_ADMIN_ROLE");
        assertTrue(ret == bytes32(0) || ret == TIMELOCK_ADMIN_ROLE);
    }
}

