contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // Ensure isOperationPending(id) is defined: the operation must be scheduled first
        // We schedule a dummy operation to make id pending, then cancel it
        // But to avoid reverts, we assume id is for a scheduled operation
        // We'll schedule a simple call with id = hashOperation(...)
        // However, fuzzing id directly may not correspond to any scheduled operation.
        // So we generate id by scheduling a known operation, then cancel its id.
        // For the property, we just need an id where isOperationPending is true.
        // The simplest: schedule an operation with minimal delay and then check the property.
        // But the property must hold for any id. So we can set up a schedule with fuzzed params.
        // To keep it simple, we bound parameters to avoid reverts.
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(keccak256(abi.encode(id))));
        bytes32 opId = c.hashOperation(target, value, data, predecessor, salt);

        // Ensure operation has enough delay (minDelay is 0, so delay >= 0)
        uint256 delay = 1 days;

        // We need proposer role to schedule. The setUp gives TIMELOCK_ADMIN_ROLE to this contract.
        // But schedule requires PROPOSER_ROLE. So we grant PROPOSER_ROLE to this contract.
        // To do that, we need TIMELOCK_ADMIN_ROLE, which we have (address(this) has it).
        // But c's methods are called from this address, so we are the caller.
        // The construct: c.schedule(target, value, data, predecessor, salt, delay) only if we have PROPOSER_ROLE.
        // We'll grant PROPOSER_ROLE to ourselves first.
        bytes32 PROPOSER_ROLE = c.PROPOSER_ROLE();
        bytes32 TIMELOCK_ADMIN_ROLE = c.TIMELOCK_ADMIN_ROLE();
        // Need to call grantRole with admin role. Since we have DEFAULT_ADMIN_ROLE? Actually TIMELOCK_ADMIN_ROLE is its own admin.
        // The constructor gave address(this) TIMELOCK_ADMIN_ROLE, so we can grant PROPOSER_ROLE to ourselves.
        c.grantRole(PROPOSER_ROLE, address(this));

        // Schedule the operation
        c.schedule(target, value, data, predecessor, salt, delay);

        // Now isOperationPending should be true
        bool pending = c.isOperationPending(opId);

        // The property: if pending, then getTimestamp(opId) > _DONE_TIMESTAMP (which is 1)
        // So: pending implies (c.getTimestamp(opId) > 1)
        // Equivalently: !pending || (c.getTimestamp(opId) > 1)
        // But getTimestamp returns uint256, so we compare with 1
        bool rule = !pending || (c.getTimestamp(opId) > 1);
        assertTrue(rule);
    }
}

