import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(uint256 delay, uint256 timeJump) public {
        // Bound delay to reasonable values
        delay = bound(delay, 1, 100 days);
        // Ensure timeJump is such that we can schedule and then skip to exactly when operation becomes ready
        vm.assume(timeJump >= delay && timeJump <= delay + 1 days);

        // Schedule an operation
        vm.warp(block.timestamp + 1000); // advance time a bit for scheduling

        // Use a valid schedule call
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(42));

        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Skip time to exactly block.timestamp + timeJump
        vm.warp(block.timestamp + timeJump);

        // Now test: if we are exactly at the scheduled timestamp (timeJump == delay), isOperationReady should be false
        // Because the bug changes > to < so that timestamp == block.timestamp returns false (since timestamp < block.timestamp is false)
        // The correct behavior: timestamp > _DONE_TIMESTAMP && timestamp <= block.timestamp should be true when equal
        bool ready = c.isOperationReady(id);

        // The property: if operation is pending (not done) and block.timestamp equals the exact scheduled timestamp, it should be ready
        // The mutant breaks this by requiring timestamp < block.timestamp, making ready false when equal
        // We schedule at block.timestamp + delay, then warp to block.timestamp + timeJump
        // The scheduled timestamp is: block.timestamp_at_schedule + delay = (block.timestamp_before_warp) + delay = (initial + 1000) + delay
        // After warp to block.timestamp + timeJump, the scheduled timestamp equals that warp time iff timeJump == delay
        // So we check: if timeJump == delay, then ready should be true (but mutant makes false)
        // General rule: if operation is not done and timestamp equals block.timestamp, it must be ready
        bool isDone = c.isOperationDone(id);
        bool isPending = c.isOperationPending(id);
        uint256 timestamp = c.getTimestamp(id);

        // The general property: for any pending operation, if block.timestamp >= timestamp, then isOperationReady must be true
        // Equivalently: if timestamp <= block.timestamp and timestamp > _DONE_TIMESTAMP, then ready is true
        // We test this by checking that when timestamp == block.timestamp, ready is always true
        // Simpler: assertTrue(ready == (timestamp > _DONE_TIMESTAMP && timestamp <= block.timestamp));
        // But that would pass on mutant too because it's the definition. Instead we assert that if timestamp == block.timestamp, then ready must be true.
        // Since we control timeJump, we can force timestamp == block.timestamp
        if (timeJump == delay) {
            assertTrue(ready, "Operation at exact scheduled time should be ready");
        }
    }
}

