    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address target, uint256 value, bytes memory data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        vm.assume(delay >= 0);
        // Schedule an operation
        c.schedule(target, value, data, predecessor, salt, delay);
        // Warp to the exact execution time
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 timestamp = c.getTimestamp(id);
        vm.warp(timestamp);
        // Now isOperationReady should return true, try to cancel
        (bool ok, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", id));
        // If isOperationReady returns true (timestamp == block.timestamp), cancel should NOT revert because the operation is ready, not pending
        // The bug makes isOperationReady return false when timestamp == block.timestamp, so cancel would succeed (non-revert) in the buggy version
        // In correct version, cancel reverts because operation is ready (not pending)
        // So the property: cancel should revert when timestamp == block.timestamp
        assertTrue(ok == false, "cancel should revert when operation is ready");
    }
}

