pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address target, uint256 value, bytes memory data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        delay = bound(delay, 1, 365 days);
        vm.assume(target != address(0));
        vm.assume(data.length <= 1000);

        c.grantRole(c.PROPOSER_ROLE(), address(this));
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        vm.warp(block.timestamp + delay);

        bool ready = c.isOperationReady(id);
        bool pending = c.isOperationPending(id);
        uint256 timestamp = c.getTimestamp(id);
        vm.assume(pending);

        try c.cancel(id) {
            assertTrue(ready == (block.timestamp >= timestamp));
        } catch {
            // cancel reverts because isOperationReady incorrectly returns false when block.timestamp == timestamp
            // In the buggy version, this will be caught; we assert the rule for the case where cancel reverts
            assertTrue(!ready);
        }
    }
}

