pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt) public {
        // Use a salt that leads to a valid operation id
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        // Schedule the operation to make it pending first
        c.schedule(target, value, data, predecessor, salt, c.getMinDelay());
        // Now cancel it
        c.cancel(id);
        // After cancel, the timestamp should be deleted => getTimestamp returns 0, which is <= _DONE_TIMESTAMP
        uint256 ts = c.getTimestamp(id);
        bool isDone = c.isOperationDone(id);
        // The general rule: after cancel, isOperationDone should return (ts == _DONE_TIMESTAMP)
        // Since ts is 0 after delete (unless it was never scheduled, but we scheduled it), this holds in P.
        // In M, isOperationDone returns (ts != _DONE_TIMESTAMP) which is true (since 0 != 1), breaking the rule.
        assertTrue(isDone == (ts == uint256(1)), "isOperationDone must equal (getTimestamp == _DONE_TIMESTAMP)");
    }
}

