pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    function testFuzz_property(bytes32 id, uint256 timestamp) public {
        // Bound timestamp to avoid overflow issues
        timestamp = bound(timestamp, 1, type(uint256).max - 1);
        // Ensure operation is not already scheduled (only timestamp 0 means unscheduled)
        // We'll schedule an operation with a salt/id? Actually we manipulate storage indirectly:
        // Use schedule to create an operation with a known id, then cancel to test.
        // But we need an operation that is "pending" (timestamp > _DONE_TIMESTAMP); after scheduling, timestamp is current time + delay.
        // To simplify, we can use the fact that getTimestamp returns a value; we don't control the mapping directly.
        // Instead, we rely on the invariant that after an execute, the timestamp becomes _DONE_TIMESTAMP (1).
        // So let's schedule, wait for delay, execute, then try to cancel – should fail.
        c.schedule(address(0), 0, "", bytes32(0), id, 0);
        vm.warp(block.timestamp + 1); // make it ready
        c.execute(address(0), 0, "", bytes32(0), id);
        // Now operation is done; cancel should revert
        vm.expectRevert("TimelockController: operation cannot be cancelled");
        c.cancel(id);
        // The test passes if the revert occurs (which it will for reference, but mutant won't revert)
        // But we need an assertTrue on a general rule.
        // We assert that the operation is done after execute.
        assertTrue(c.isOperationDone(id), "Operation should be done");
    }
}

